<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $d=journeys_input(); if(!journeys_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $jid=(int)($d['journey_id']??0); $action=(string)($d['action']??''); if(!in_array($action,['accept','reject'],true)){ApiResponse::validation(['action'=>'Invalid action.']);exit;} $status=$action==='accept'?'accepted':'rejected'; $j=$jid>0?journeys_find($db,$jid):null; if(!$j){ApiResponse::notFound('Journey not found.');exit;} if(journeys_is_blocked($db,(int)$j['owner_id'],$uid)){ApiResponse::forbidden('Not allowed.');exit;} $db->beginTransaction(); $s=$db->prepare("UPDATE journey_invitations SET status=:status, responded_at=NOW() WHERE journey_id=:j AND invitee_id=:u AND status='pending'"); $s->execute(['status'=>$status,'j'=>$jid,'u'=>$uid]); if($s->rowCount()<1){throw new RuntimeException('Pending invitation not found.');} $p=$db->prepare("UPDATE journey_participants SET status=:status, responded_at=NOW() WHERE journey_id=:j AND user_id=:u AND status='pending'"); $p->execute(['status'=>$status,'j'=>$jid,'u'=>$uid]); NotificationService::createOnce($db,(int)$j['owner_id'],$uid,NotificationService::TYPE_JOURNEY_INVITATION,'journey',$jid,$status==='accepted'?'accepted your journey invitation.':'rejected your journey invitation.'); $db->commit(); ApiResponse::success([],'Invitation updated.'); }catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();Logger::error('Journey respond failed',['error'=>$e->getMessage()]);ApiResponse::serverError($e instanceof RuntimeException?$e->getMessage():'Unable to respond.');}
?>
